//! The packs the user can download (never bundled): the ONNX Runtime library, the Kokoro model
//! and its voices, Piper voices. Everything is pinned by SHA-256 in `catalog_data.rs`
//! (generated by `build-aux/tts-catalog.py`) and shown with its licence before the download.

use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::catalog_data as data;

/// How a file is taken out of what is downloaded.
#[derive(Debug, Clone, PartialEq)]
pub enum ArchiveKind {
    /// A `.tgz` downloaded whole; the member whose path ends with `Extract::member_suffix`.
    Tgz,
    /// One member of a big zip on a server that does Range requests: only that member's bytes are
    /// downloaded (the directory at the end of the zip tells where they are).
    ZipMember { member: String },
}

/// Where a file comes from inside an archive, and what it must be once taken out.
#[derive(Debug, Clone, PartialEq)]
pub struct Extract {
    pub kind: ArchiveKind,
    /// `Tgz`: the archive member whose path ends with this.
    pub member_suffix: String,
    /// SHA-256 and size of the extracted file, pinned and checked after extraction. It is the same
    /// for every origin that ships the same build.
    pub sha256: String,
    pub size: u64,
}

/// Another place the same file can be fetched from (tried in the order of the list when the
/// first fails or is too slow).
#[derive(Debug, Clone, PartialEq)]
pub struct Origin {
    pub url: String,
    /// SHA-256 of what is downloaded (empty: not a whole file, see `ArchiveKind::ZipMember`).
    pub sha256: String,
    /// Bytes to download.
    pub size: u64,
    pub extract: Option<Extract>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct FileSpec {
    /// Where the file ends up, relative to the directory of the pack. With `extract`, the
    /// downloaded archive is a temporary and this is the extracted member.
    pub rel: String,
    pub url: String,
    pub sha256: String,
    /// Size of the download in bytes.
    pub size: u64,
    pub extract: Option<Extract>,
    /// More origins for the same file, after this one. Models (Hugging Face) can get mirrors here.
    pub fallbacks: Vec<Origin>,
}

impl FileSpec {
    /// The primary origin first, then the fallbacks.
    pub fn origins(&self) -> Vec<Origin> {
        let mut v = vec![Origin {
            url: self.url.clone(),
            sha256: self.sha256.clone(),
            size: self.size,
            extract: self.extract.clone(),
        }];
        v.extend(self.fallbacks.iter().cloned());
        v
    }

    /// The hash the installed file must have: the pinned hash of the extracted file, else of the download.
    pub fn installed_sha(&self) -> &str {
        self.extract.as_ref().map_or(&self.sha256, |x| &x.sha256)
    }

    pub fn installed_size(&self) -> u64 {
        self.extract.as_ref().map_or(self.size, |x| x.size)
    }

    /// Hashes an install marker may carry for this file: the extracted file's, and (markers of
    /// earlier versions) the archive's of any origin.
    fn accepts_marker_sha(&self, sha: &str) -> bool {
        sha == self.installed_sha()
            || sha == self.sha256
            || self.fallbacks.iter().any(|o| o.sha256 == sha)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PackKind {
    Runtime,
    KokoroModel,
    KokoroVoices,
    PiperVoice,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Pack {
    pub id: String,
    pub kind: PackKind,
    pub title: String,
    pub summary: String,
    /// Two-letter codes of the languages it speaks (empty: not a voice).
    pub languages: Vec<String>,
    pub license_name: String,
    pub license_url: String,
    /// What the licence means for the user, in a few lines.
    pub license_note: String,
    /// Packs that have to be installed too.
    pub requires: Vec<String>,
    /// Directory under the store root.
    pub dir: String,
    pub files: Vec<FileSpec>,
}

impl Pack {
    pub fn download_size(&self) -> u64 {
        self.files.iter().map(|f| f.size).sum()
    }
}

/// The directory the packs live in (`$XDG_DATA_HOME/bookx/tts`, or what the app passes).
#[derive(Debug, Clone)]
pub struct Store {
    pub root: PathBuf,
}

#[derive(Serialize, Deserialize)]
struct Marker {
    id: String,
    files: Vec<(String, String, u64)>,
}

impl Store {
    pub fn new(root: impl Into<PathBuf>) -> Store {
        Store { root: root.into() }
    }

    pub fn dir_of(&self, p: &Pack) -> PathBuf {
        self.root.join(&p.dir)
    }

    fn marker(&self, p: &Pack) -> PathBuf {
        self.dir_of(p).join(format!(".installed-{}.json", p.id))
    }

    /// Complete and verified at download time, and all files still there.
    pub fn is_installed(&self, p: &Pack) -> bool {
        let Ok(text) = std::fs::read_to_string(self.marker(p)) else {
            return false;
        };
        let Ok(m) = serde_json::from_str::<Marker>(&text) else {
            return false;
        };
        m.id == p.id
            && p.files.iter().all(|f| {
                let path = self.dir_of(p).join(&f.rel);
                let Some(entry) = m
                    .files
                    .iter()
                    .find(|x| x.0 == f.rel && f.accepts_marker_sha(&x.1))
                else {
                    return false;
                };
                let Ok(md) = std::fs::metadata(&path) else {
                    return false;
                };
                // the pinned size of the extracted file when the marker has its hash; a marker of an
                // earlier version (archive hash) cannot say, and the file must just be there
                if entry.1 == f.installed_sha() {
                    md.len() == f.installed_size()
                } else {
                    f.extract.is_some() || md.len() == f.size
                }
            })
    }

    /// True when a download was started and not finished (a `.part` file is left from an earlier run).
    pub fn has_partial_download(&self) -> bool {
        partial_in(&self.root, 0)
    }

    /// The same for one pack.
    pub fn pack_has_partial(&self, p: &Pack) -> bool {
        partial_in(&self.dir_of(p), 0)
    }

    pub fn mark_installed(&self, p: &Pack) -> std::io::Result<()> {
        let m = Marker {
            id: p.id.clone(),
            files: p
                .files
                .iter()
                .map(|f| {
                    (
                        f.rel.clone(),
                        f.installed_sha().to_string(),
                        f.installed_size(),
                    )
                })
                .collect(),
        };
        std::fs::create_dir_all(self.dir_of(p))?;
        std::fs::write(self.marker(p), serde_json::to_vec(&m).unwrap_or_default())
    }

    /// Deletes a pack from the disk.
    pub fn remove(&self, p: &Pack) -> std::io::Result<()> {
        let _ = std::fs::remove_file(self.marker(p));
        for f in &p.files {
            let path = self.dir_of(p).join(&f.rel);
            let _ = std::fs::remove_file(&path);
            let _ = std::fs::remove_file(path.with_extension("part"));
        }
        // drop the directory when nothing else lives there
        let _ = std::fs::remove_dir(self.dir_of(p).join("voices"));
        let _ = std::fs::remove_dir(self.dir_of(p));
        Ok(())
    }

    /// The ONNX Runtime library, when it is installed (or `$ORT_DYLIB_PATH` names one).
    pub fn runtime_lib(&self) -> Option<PathBuf> {
        if let Some(p) = std::env::var_os("ORT_DYLIB_PATH") {
            let p = PathBuf::from(p);
            if p.exists() {
                return Some(p);
            }
        }
        let p = self.root.join("onnxruntime").join(RUNTIME_LIB);
        p.exists().then_some(p)
    }
}

fn partial_in(dir: &Path, depth: u32) -> bool {
    let Ok(rd) = std::fs::read_dir(dir) else {
        return false;
    };
    rd.flatten().any(|e| {
        let p = e.path();
        if p.is_dir() {
            depth < 3 && partial_in(&p, depth + 1)
        } else {
            p.extension().is_some_and(|x| x == "part")
        }
    })
}

pub const RUNTIME_LIB: &str = "libonnxruntime.so";

fn spec(rel: &str, url: String, sha: &str, size: u64) -> FileSpec {
    FileSpec {
        rel: rel.to_string(),
        url,
        sha256: sha.to_string(),
        size,
        extract: None,
        fallbacks: vec![],
    }
}

fn kokoro_url(path: &str) -> String {
    format!(
        "https://huggingface.co/onnx-community/Kokoro-82M-v1.0-ONNX/resolve/{}/{path}",
        data::KOKORO_REV
    )
}

/// The Kokoro voices speak with the phonemes of espeak-ng; the language is the first letter
/// of the voice name.
pub fn kokoro_voice_language(name: &str) -> &'static str {
    match name.chars().next() {
        Some('a') | Some('b') => "en",
        Some('e') => "es",
        Some('f') => "fr",
        Some('h') => "hi",
        Some('i') => "it",
        Some('p') => "pt",
        Some('j') => "ja",
        Some('z') => "zh",
        _ => "",
    }
}

/// Languages Kokoro can read here: Japanese and Chinese need other grapheme-to-phoneme tools
/// than espeak-ng and are left out.
pub const KOKORO_LANGUAGES: [&str; 6] = ["en", "es", "fr", "hi", "it", "pt"];

/// The ONNX Runtime library. Origins, in the order they are tried:
///
/// 1. **NuGet** (`Microsoft.ML.OnnxRuntime`, a fast CDN): the official library is one member of a
///    160 MB zip of all platforms; only that member (about 10 MB) is read with Range requests.
/// 2. **GitHub release** archive (about 11 MB), the original place, slow on some networks.
///
/// Both give the same `libonnxruntime.so` (same build, same SHA-256), which is what is pinned.
/// (The conda-forge packages were looked at and left out: their library is linked against conda's
/// own protobuf and abseil and does not load outside a conda environment.)
fn runtime_pack() -> Pack {
    let (gh_url, gh_sha, gh_size, (lib_sha, lib_size), (member, nuget_size)) =
        if cfg!(target_arch = "aarch64") {
            let g = data::ORT_AARCH64;
            (
                g.0,
                g.1,
                g.2,
                data::ORT_LIB_AARCH64,
                data::ORT_NUGET_AARCH64,
            )
        } else {
            let g = data::ORT_X64;
            (g.0, g.1, g.2, data::ORT_LIB_X64, data::ORT_NUGET_X64)
        };
    let github = Origin {
        url: gh_url.into(),
        sha256: gh_sha.into(),
        size: gh_size,
        extract: Some(Extract {
            kind: ArchiveKind::Tgz,
            member_suffix: format!("/lib/libonnxruntime.so.{}", data::ORT_VERSION),
            sha256: lib_sha.into(),
            size: lib_size,
        }),
    };
    Pack {
        id: "onnxruntime".into(),
        kind: PackKind::Runtime,
        title: format!("ONNX Runtime {}", data::ORT_VERSION),
        summary: "Microsoft's inference library that runs the voice models on the CPU.".into(),
        languages: vec![],
        license_name: "MIT".into(),
        license_url: "https://github.com/microsoft/onnxruntime/blob/main/LICENSE".into(),
        license_note: "Free to use and redistribute. Downloaded from Microsoft's NuGet package, or from the GitHub release when that is slow."
            .into(),
        requires: vec![],
        dir: "onnxruntime".into(),
        files: vec![FileSpec {
            rel: RUNTIME_LIB.into(),
            url: data::ORT_NUGET_URL.into(),
            sha256: String::new(),
            size: nuget_size,
            extract: Some(Extract {
                kind: ArchiveKind::ZipMember {
                    member: member.into(),
                },
                member_suffix: String::new(),
                sha256: lib_sha.into(),
                size: lib_size,
            }),
            fallbacks: vec![github],
        }],
    }
}

const KOKORO_LICENSE_NOTE: &str = "Apache License 2.0: free to use, also for the audio it makes. \
Kokoro was trained on permissively licensed and synthetic speech. The text is turned into \
phonemes by espeak-ng (GPL-3.0), which must be installed on your system.";

fn kokoro_packs() -> Vec<Pack> {
    let mut v = Vec::new();
    for (key, (rel, sha, size), title, summary) in [
        (
            "kokoro-int8",
            data::KOKORO_INT8,
            "Kokoro 82M (small, int8)",
            "Natural-sounding voices, 92 MB. Several times faster than real time on a laptop CPU.",
        ),
        (
            "kokoro-fp32",
            data::KOKORO_FP32,
            "Kokoro 82M (full precision)",
            "The same model without quantization, 326 MB: slightly cleaner (the small one can sound a little rough on some voices), about the same speed.",
        ),
    ] {
        let file = rel.rsplit('/').next().unwrap_or(rel);
        v.push(Pack {
            id: key.into(),
            kind: PackKind::KokoroModel,
            title: title.into(),
            summary: summary.into(),
            languages: KOKORO_LANGUAGES.iter().map(|s| s.to_string()).collect(),
            license_name: "Apache-2.0".into(),
            license_url: "https://huggingface.co/hexgrad/Kokoro-82M".into(),
            license_note: KOKORO_LICENSE_NOTE.into(),
            requires: vec!["onnxruntime".into(), "kokoro-voices".into()],
            dir: "kokoro".into(),
            files: vec![spec(file, kokoro_url(rel), sha, size)],
        });
    }
    v.push(Pack {
        id: "kokoro-voices".into(),
        kind: PackKind::KokoroVoices,
        title: "Kokoro voices".into(),
        summary: "54 voices in English (American and British), Spanish, French, Hindi, Italian and Brazilian Portuguese (and Japanese and Chinese, which Bookx cannot use yet).".into(),
        languages: KOKORO_LANGUAGES.iter().map(|s| s.to_string()).collect(),
        license_name: "Apache-2.0".into(),
        license_url: "https://huggingface.co/hexgrad/Kokoro-82M".into(),
        license_note: KOKORO_LICENSE_NOTE.into(),
        requires: vec![],
        dir: "kokoro".into(),
        files: data::KOKORO_VOICES
            .iter()
            .map(|(name, sha, size)| {
                spec(
                    &format!("voices/{name}.bin"),
                    kokoro_url(&format!("voices/{name}.bin")),
                    sha,
                    *size,
                )
            })
            .collect(),
    });
    v
}

/// "en_US-lessac-medium" -> language "en", name "Lessac (US English, medium)".
fn piper_pack(
    path: &str,
    onnx_sha: &str,
    onnx_size: u64,
    json_sha: &str,
    json_size: u64,
    license: &str,
) -> Pack {
    let parts: Vec<&str> = path.split('/').collect();
    let (lang, locale, speaker, quality) = (parts[0], parts[1], parts[2], parts[3]);
    let id = format!("{locale}-{speaker}-{quality}");
    let url = |f: &str| {
        format!(
            "https://huggingface.co/rhasspy/piper-voices/resolve/{}/{path}/{f}",
            data::PIPER_REV
        )
    };
    let nc = license.contains("-nc") || license.contains("NC");
    let note = format!(
        "Piper's engine is not used (Bookx runs the voice file itself). The voice was trained on a \
dataset licensed as: {license}.{} The model card has the details: \
https://huggingface.co/rhasspy/piper-voices/blob/main/{path}/MODEL_CARD. Needs espeak-ng \
(GPL-3.0) installed for the phonemes.",
        if nc {
            " This is a non-commercial licence: fine for reading your own books, not for a product."
        } else {
            ""
        }
    );
    Pack {
        id: format!("piper-{id}"),
        kind: PackKind::PiperVoice,
        title: format!("{} ({locale}, {quality})", capitalize(speaker)),
        summary: format!(
            "Piper voice, {} MB. Fast and light, less lifelike than Kokoro.",
            onnx_size / 1_000_000
        ),
        languages: vec![lang.to_string()],
        license_name: license.to_string(),
        license_url: format!(
            "https://huggingface.co/rhasspy/piper-voices/blob/main/{path}/MODEL_CARD"
        ),
        license_note: note,
        requires: vec!["onnxruntime".into()],
        dir: format!("piper/{id}"),
        files: vec![
            spec(
                &format!("{id}.onnx"),
                url(&format!("{id}.onnx")),
                onnx_sha,
                onnx_size,
            ),
            spec(
                &format!("{id}.onnx.json"),
                url(&format!("{id}.onnx.json")),
                json_sha,
                json_size,
            ),
        ],
    }
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

/// Every pack Bookx knows.
pub fn catalog() -> Vec<Pack> {
    let mut v = vec![runtime_pack()];
    v.extend(kokoro_packs());
    for (path, osha, osize, jsha, jsize, lic) in data::PIPER_VOICES {
        v.push(piper_pack(path, osha, *osize, jsha, *jsize, lic));
    }
    v
}

pub fn find_pack(id: &str) -> Option<Pack> {
    catalog().into_iter().find(|p| p.id == id)
}

/// The packs to download to get `id` working: its requirements first, those already installed
/// left out.
pub fn install_plan(all: &[Pack], store: &Store, id: &str) -> Vec<Pack> {
    fn walk(all: &[Pack], id: &str, out: &mut Vec<String>) {
        if out.iter().any(|x| x == id) {
            return;
        }
        if let Some(p) = all.iter().find(|p| p.id == id) {
            for r in &p.requires {
                walk(all, r, out);
            }
            out.push(id.to_string());
        }
    }
    let mut ids = Vec::new();
    walk(all, id, &mut ids);
    ids.iter()
        .filter_map(|i| all.iter().find(|p| &p.id == i))
        .filter(|p| !store.is_installed(p))
        .cloned()
        .collect()
}

/// The packs that make Kokoro speak: the runtime, the voices and one model.
pub fn kokoro_model_pack(prefs_model: &str) -> &'static str {
    if prefs_model == "fp32" {
        "kokoro-fp32"
    } else {
        "kokoro-int8"
    }
}

/// An installed Kokoro: model file and voices directory. `model` is the model the user prefers
/// (`int8` or `fp32`); when only the other one is installed, that one is used: any complete
/// installed Kokoro reads, whatever the setting says.
pub fn kokoro_paths(store: &Store, model: &str) -> Option<(PathBuf, PathBuf)> {
    let order = if model == "fp32" {
        ["fp32", "int8"]
    } else {
        ["int8", "fp32"]
    };
    order.iter().find_map(|m| kokoro_paths_exact(store, m))
}

fn kokoro_paths_exact(store: &Store, model: &str) -> Option<(PathBuf, PathBuf)> {
    let all = catalog();
    let m = all.iter().find(|p| p.id == kokoro_model_pack(model))?;
    let v = all.iter().find(|p| p.id == "kokoro-voices")?;
    (store.is_installed(m) && store.is_installed(v)).then(|| {
        (
            store.dir_of(m).join(&m.files[0].rel),
            store.dir_of(v).join("voices"),
        )
    })
}

/// Brings packs from older places into `root`: any top-level folder of a legacy root that holds an
/// install marker moves over when `root` does not have a folder of that name yet. Returns the names
/// moved. Nothing is overwritten and nothing is downloaded; a folder that cannot be moved (another
/// disk) is copied, and the old one is left alone then.
pub fn migrate_legacy(root: &Path, legacy: &[PathBuf]) -> Vec<String> {
    let mut moved = Vec::new();
    for old in legacy {
        if old == root {
            continue;
        }
        let Ok(rd) = std::fs::read_dir(old) else {
            continue;
        };
        for e in rd.flatten() {
            let from = e.path();
            let name = e.file_name().to_string_lossy().into_owned();
            let has_marker = std::fs::read_dir(&from).is_ok_and(|d| {
                d.flatten().any(|f| {
                    let n = f.file_name().to_string_lossy().into_owned();
                    n.starts_with(".installed-") && n.ends_with(".json")
                }) || from.join("voices").is_dir()
                    || std::fs::read_dir(&from).is_ok_and(|d2| {
                        d2.flatten().any(|sub| {
                            sub.path()
                                .join(format!(
                                    ".installed-piper-{}.json",
                                    sub.file_name().to_string_lossy()
                                ))
                                .exists()
                        })
                    })
            });
            let to = root.join(&name);
            if !has_marker || to.exists() {
                continue;
            }
            let _ = std::fs::create_dir_all(root);
            if std::fs::rename(&from, &to).is_ok() || copy_tree(&from, &to).is_ok() {
                moved.push(name);
            }
        }
    }
    moved
}

fn copy_tree(from: &Path, to: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(to)?;
    for e in std::fs::read_dir(from)?.flatten() {
        let (a, b) = (e.path(), to.join(e.file_name()));
        if a.is_dir() {
            copy_tree(&a, &b)?;
        } else {
            std::fs::copy(&a, &b)?;
        }
    }
    Ok(())
}

/// The installed Piper voices as (id, language, onnx path).
pub fn piper_installed(store: &Store) -> Vec<(String, String, PathBuf)> {
    catalog()
        .into_iter()
        .filter(|p| p.kind == PackKind::PiperVoice && store.is_installed(p))
        .map(|p| {
            (
                p.id.trim_start_matches("piper-").to_string(),
                p.languages[0].clone(),
                store.dir_of(&p).join(&p.files[0].rel),
            )
        })
        .collect()
}

/// Is the library file there and is it ours? (Used by the settings page.)
pub fn runtime_ready(store: &Store) -> bool {
    store.runtime_lib().is_some()
}

pub fn dir_size(p: &Path) -> u64 {
    let Ok(rd) = std::fs::read_dir(p) else {
        return 0;
    };
    rd.flatten()
        .map(|e| {
            let p = e.path();
            if p.is_dir() {
                dir_size(&p)
            } else {
                e.metadata().map(|m| m.len()).unwrap_or(0)
            }
        })
        .sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp() -> PathBuf {
        let d = std::env::temp_dir().join(format!("bookx-models-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&d).unwrap();
        d
    }

    #[test]
    fn the_catalog_is_complete_and_pinned() {
        let all = catalog();
        let ids: Vec<&str> = all.iter().map(|p| p.id.as_str()).collect();
        for want in [
            "onnxruntime",
            "kokoro-int8",
            "kokoro-fp32",
            "kokoro-voices",
            "piper-en_US-lessac-medium",
            "piper-de_DE-thorsten-medium",
        ] {
            assert!(ids.contains(&want), "{want} missing in {ids:?}");
        }
        let mut seen = std::collections::HashSet::new();
        for p in &all {
            assert!(seen.insert(&p.id), "duplicate id {}", p.id);
            assert!(
                !p.license_name.is_empty() && !p.license_note.is_empty(),
                "{}",
                p.id
            );
            assert!(!p.files.is_empty());
            for f in &p.files {
                for o in f.origins() {
                    assert!(o.url.starts_with("https://"), "{}", o.url);
                    assert!(o.size > 0);
                    match &o.extract {
                        // a member of a zip has no hash of its own: the extracted file is pinned
                        Some(Extract {
                            kind: ArchiveKind::ZipMember { member },
                            ..
                        }) => {
                            assert!(o.sha256.is_empty() && !member.is_empty(), "{}", o.url);
                        }
                        _ => {
                            assert_eq!(o.sha256.len(), 64, "{} {}", p.id, f.rel);
                            assert!(o.sha256.chars().all(|c| c.is_ascii_hexdigit()));
                        }
                    }
                    if let Some(x) = &o.extract {
                        assert_eq!(x.sha256.len(), 64, "{} {}", p.id, f.rel);
                        assert!(x.sha256.chars().all(|c| c.is_ascii_hexdigit()));
                        assert!(x.size > 0);
                        assert_eq!(
                            x.sha256,
                            f.installed_sha(),
                            "every origin ships the same library"
                        );
                    }
                }
                assert!(!f.rel.contains(".."), "{}", f.rel);
            }
            for r in &p.requires {
                assert!(ids.contains(&r.as_str()), "{} requires unknown {r}", p.id);
            }
        }
        // nothing is meant to be huge: the biggest single download stays below 500 MB
        assert!(all.iter().all(|p| p.download_size() < 500_000_000));
        assert!(find_pack("kokoro-voices").unwrap().files.len() > 40);
        assert!(find_pack("nope").is_none());
    }

    #[test]
    fn the_plan_lists_requirements_first_and_skips_what_is_installed() {
        let root = tmp();
        let store = Store::new(&root);
        let all = catalog();
        let plan: Vec<String> = install_plan(&all, &store, "kokoro-int8")
            .into_iter()
            .map(|p| p.id)
            .collect();
        assert_eq!(plan, ["onnxruntime", "kokoro-voices", "kokoro-int8"]);
        // the runtime is there
        let rt = all.iter().find(|p| p.id == "onnxruntime").unwrap();
        std::fs::create_dir_all(store.dir_of(rt)).unwrap();
        // a library of the pinned size (sparse: cheap) and the marker the downloader writes
        let lib = std::fs::File::create(store.dir_of(rt).join(RUNTIME_LIB)).unwrap();
        lib.set_len(rt.files[0].installed_size()).unwrap();
        assert!(!store.is_installed(rt), "no marker yet");
        store.mark_installed(rt).unwrap();
        assert!(store.is_installed(rt));
        let plan: Vec<String> = install_plan(&all, &store, "piper-de_DE-thorsten-medium")
            .into_iter()
            .map(|p| p.id)
            .collect();
        assert_eq!(plan, ["piper-de_DE-thorsten-medium"]);
        assert!(runtime_ready(&store) || std::env::var_os("ORT_DYLIB_PATH").is_some());
        store.remove(rt).unwrap();
        assert!(!store.is_installed(rt));
        std::fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn a_truncated_or_unmarked_file_is_not_installed() {
        let root = tmp();
        let store = Store::new(&root);
        let p = find_pack("piper-en_US-lessac-medium").unwrap();
        std::fs::create_dir_all(store.dir_of(&p)).unwrap();
        for f in &p.files {
            std::fs::write(store.dir_of(&p).join(&f.rel), b"short").unwrap();
        }
        store.mark_installed(&p).unwrap();
        assert!(!store.is_installed(&p), "wrong size");
        assert!(piper_installed(&store).is_empty());
        std::fs::remove_dir_all(&root).ok();
    }

    #[test]
    fn kokoro_voices_know_their_language() {
        assert_eq!(kokoro_voice_language("af_heart"), "en");
        assert_eq!(kokoro_voice_language("bm_george"), "en");
        assert_eq!(kokoro_voice_language("ff_siwis"), "fr");
        assert_eq!(kokoro_voice_language("ef_dora"), "es");
        assert_eq!(kokoro_voice_language("hf_alpha"), "hi");
        assert_eq!(kokoro_voice_language("if_sara"), "it");
        assert_eq!(kokoro_voice_language("pf_dora"), "pt");
        assert_eq!(kokoro_voice_language("zf_xiaobei"), "zh");
        assert_eq!(kokoro_voice_language("?"), "");
        assert_eq!(kokoro_model_pack("fp32"), "kokoro-fp32");
        assert_eq!(kokoro_model_pack("whatever"), "kokoro-int8");
    }

    #[test]
    fn non_commercial_piper_voices_say_so() {
        let tr = find_pack("piper-tr_TR-dfki-medium").unwrap();
        assert!(
            tr.license_note.contains("non-commercial"),
            "{}",
            tr.license_note
        );
        let de = find_pack("piper-de_DE-thorsten-medium").unwrap();
        assert!(!de.license_note.contains("non-commercial"));
        assert_eq!(de.languages, ["de"]);
        assert_eq!(de.requires, ["onnxruntime"]);
    }

    #[test]
    fn an_unfinished_download_is_noticed_per_pack_and_overall() {
        let dir = std::env::temp_dir().join(format!("bookx-partial-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let store = Store::new(&dir);
        let all = catalog();
        let a = &all[1];
        assert!(!store.has_partial_download());
        std::fs::create_dir_all(store.dir_of(a)).unwrap();
        std::fs::write(store.dir_of(a).join("model.onnx.part"), b"x").unwrap();
        assert!(store.has_partial_download());
        assert!(store.pack_has_partial(a));
        assert!(!store.pack_has_partial(&all[0]));
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Writes the files of `p` with their real sizes (sparse, so cheap) and the install marker.
    fn fake_install(store: &Store, p: &Pack) {
        for f in &p.files {
            let path = store.dir_of(p).join(&f.rel);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::File::create(&path)
                .unwrap()
                .set_len(f.size)
                .unwrap();
        }
        store.mark_installed(p).unwrap();
    }

    fn pack(id: &str) -> Pack {
        find_pack(id).unwrap()
    }

    fn fresh(name: &str) -> Store {
        let d = std::env::temp_dir().join(format!("bookx-models-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).unwrap();
        Store::new(d)
    }

    #[test]
    fn any_complete_kokoro_is_used_whatever_model_the_setting_prefers() {
        let store = fresh("any");
        assert!(kokoro_paths(&store, "int8").is_none(), "nothing installed");
        fake_install(&store, &pack("kokoro-voices"));
        assert!(
            kokoro_paths(&store, "int8").is_none(),
            "voices alone are not a voice"
        );
        fake_install(&store, &pack("kokoro-int8"));
        // the owner's case: the setting says fp32, only the small model is installed
        let (m, v) = kokoro_paths(&store, "fp32").expect("int8 is used");
        assert!(m.ends_with("model_quantized.onnx"), "{m:?}");
        assert!(v.ends_with("voices"));
        assert!(kokoro_paths(&store, "int8").is_some());
        // both installed: the preferred one wins
        fake_install(&store, &pack("kokoro-fp32"));
        let fp = kokoro_paths(&store, "fp32").unwrap().0;
        let q = kokoro_paths(&store, "int8").unwrap().0;
        assert_ne!(fp, q);
        let _ = std::fs::remove_dir_all(&store.root);
    }

    #[test]
    fn partial_or_wrong_files_do_not_count_as_installed() {
        let store = fresh("partial");
        let model = pack("kokoro-int8");
        fake_install(&store, &pack("kokoro-voices"));
        fake_install(&store, &model);
        assert!(kokoro_paths(&store, "int8").is_some());
        // a file of the wrong size (cut short)
        let path = store.dir_of(&model).join(&model.files[0].rel);
        std::fs::File::options()
            .write(true)
            .open(&path)
            .unwrap()
            .set_len(1000)
            .unwrap();
        assert!(kokoro_paths(&store, "int8").is_none());
        // restored, then the marker goes: not verified, so not installed
        std::fs::File::options()
            .write(true)
            .open(&path)
            .unwrap()
            .set_len(model.files[0].size)
            .unwrap();
        assert!(kokoro_paths(&store, "int8").is_some());
        std::fs::remove_file(
            store
                .dir_of(&model)
                .join(format!(".installed-{}.json", model.id)),
        )
        .unwrap();
        assert!(kokoro_paths(&store, "int8").is_none());
        // a marker of another pack is no marker
        let other = pack("kokoro-fp32");
        std::fs::create_dir_all(store.dir_of(&model)).unwrap();
        std::fs::copy(
            store
                .dir_of(&pack("kokoro-voices"))
                .join(".installed-kokoro-voices.json"),
            store
                .dir_of(&model)
                .join(format!(".installed-{}.json", model.id)),
        )
        .unwrap();
        assert!(kokoro_paths(&store, "int8").is_none());
        assert!(!store.is_installed(&other));
        let _ = std::fs::remove_dir_all(&store.root);
    }

    #[test]
    fn packs_from_an_older_place_are_moved_in_and_never_overwrite() {
        let store = fresh("legacy");
        let old = fresh("legacy-old");
        fake_install(&old, &pack("kokoro-voices"));
        fake_install(&old, &pack("kokoro-int8"));
        fake_install(&old, &pack("onnxruntime"));
        std::fs::create_dir_all(old.root.join("junk")).unwrap();
        std::fs::write(old.root.join("junk/readme.txt"), b"x").unwrap();
        assert!(kokoro_paths(&store, "int8").is_none());
        let moved = migrate_legacy(&store.root, &[old.root.clone(), store.root.clone()]);
        assert_eq!(
            moved.len(),
            2,
            "{moved:?}: the kokoro and the runtime folders, not the junk"
        );
        assert!(
            kokoro_paths(&store, "int8").is_some(),
            "the old install is usable now"
        );
        assert!(store.runtime_lib().is_some());
        assert!(old.root.join("junk").exists(), "unrelated folders stay");
        // a second run has nothing to do, and an existing folder is never replaced
        assert!(migrate_legacy(&store.root, std::slice::from_ref(&old.root)).is_empty());
        let _ = std::fs::remove_dir_all(&store.root);
        let _ = std::fs::remove_dir_all(&old.root);
    }

    #[test]
    fn an_installed_piper_voice_in_an_older_place_is_moved_in_too() {
        let store = fresh("legacy-piper");
        let old = fresh("legacy-piper-old");
        let voice = catalog()
            .into_iter()
            .find(|p| p.kind == PackKind::PiperVoice)
            .unwrap();
        fake_install(&old, &voice);
        assert_eq!(piper_installed(&store).len(), 0);
        migrate_legacy(&store.root, std::slice::from_ref(&old.root));
        assert_eq!(piper_installed(&store).len(), 1);
        let _ = std::fs::remove_dir_all(&store.root);
        let _ = std::fs::remove_dir_all(&old.root);
    }
}
